contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 inputAmount) public {
        require(inputAmount > 0 && inputAmount <= 10**24);
        uint256 vBase = c.virtualBaseTokenReserves();
        uint256 vNft = c.virtualNftReserves();
        uint256 feeRate = c.feeRate();
        require(vNft + inputAmount > 0);
        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);
