}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 outputAmount) public {
        uint256 vBase = c.virtualBaseTokenReserves();
        uint256 vNft = c.virtualNftReserves();
        uint256 feeRate = c.feeRate();
        uint256 protocolFeeRate = Factory(c.factory()).protocolFeeRate();
        require(outputAmount > 0 && outputAmount < vNft && outputAmount <= 10**6);
