        uint256 expectedFee = grossInput * feeRate / 10_000;
        uint256 expectedProtocolFee = grossInput * protocolFeeRate / 10_000;
        assert(netInputAmount == grossInput + feeAmount + protocolFeeAmount && feeAmount == expectedFee && protocolFeeAmount == expectedProtocolFee);
    }
    receive() external payable {}
}

