contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        require(feeRate <= 5_000);

        bool firstOk;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        bool secondReverted;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            firstOk &&
            secondReverted &&
            c.initialized() &&
            c.baseToken() == baseToken &&
            c.nft() == nft &&
            c.virtualBaseTokenReserves() == virtualBaseTokenReserves &&
            c.virtualNftReserves() == virtualNftReserves &&
            c.changeFee() == changeFee &&
            c.feeRate() == feeRate &&
            c.merkleRoot() == merkleRoot &&
            c.useStolenNftOracle() == useStolenNftOracle &&
            c.payRoyalties() == payRoyalties
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256[] memory tokenIds,
        uint256[] memory tokenWeights,
        bytes32[] memory proof,
        bool[] memory flags
    ) public {
        require(tokenIds.length == tokenWeights.length);
        require(tokenIds.length <= 8);

        // Fresh pool: merkle root is zero, so the function must fall back to
        // the default weight of 1e18 per token id, ignoring weights/proof.
        C.MerkleMultiProof memory mp = C.MerkleMultiProof(proof, flags);
        uint256 sum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mp);

        assert(
            c.merkleRoot() == bytes32(0) &&
            sum == tokenIds.length * 1e18
        );
    }

    receive() external payable {}
}

