contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 baseReserves,
        uint128 nftReserves,
        uint16 feeRate,
        uint256 inputAmount
    ) public {
        require(nftReserves > 0);
        require(feeRate <= 5000);
        require(inputAmount > 0 && inputAmount <= 1e30);

        c.initialize(
            address(0),
            address(0xdead),
            baseReserves,
            nftReserves,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        uint256 base = uint256(baseReserves);
        uint256 nft = uint256(nftReserves);
        uint256 out = inputAmount * base / (nft + inputAmount);
        uint256 protoRate = Factory(c.factory()).protocolFeeRate();

        (uint256 net, uint256 fee, uint256 proto) = c.sellQuote(inputAmount);

        assert(
            net + fee + proto == out &&
            fee == out * feeRate / 10_000 &&
            proto == out * protoRate / 10_000
        );
    }

    receive() external payable {}
}

