contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bool useStolenNftOracle,
        bool payRoyalties,
        uint128 otherVirtualBase
    ) public {
        require(feeRate <= 5_000, "fee rate too high");

        c.initialize(
            address(0),
            address(0),
            virtualBase,
            virtualNft,
            changeFee,
            feeRate,
            bytes32(0),
            useStolenNftOracle,
            payRoyalties
        );

        bool reverted;
        try c.initialize(
            address(0),
            address(0),
            otherVirtualBase,
            virtualNft,
            changeFee,
            feeRate,
            bytes32(0),
            useStolenNftOracle,
            payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            c.initialized() &&
            c.feeRate() == feeRate &&
            c.changeFee() == changeFee &&
            c.virtualBaseTokenReserves() == virtualBase &&
            c.virtualNftReserves() == virtualNft &&
            c.useStolenNftOracle() == useStolenNftOracle &&
            c.payRoyalties() == payRoyalties &&
            c.merkleRoot() == bytes32(0)
        );
    }

    receive() external payable {}
}
